{
  const samples = 400;
  const pts = routeCurve.getSpacedPoints(samples);
  for (const s of STOPS) {
    let bestT = s.t, bestD = Infinity;
    for (let i = 0; i <= samples; i++) {
      const p = pts[i];
      const d = Math.hypot(p.x - s.pos.x, p.z - s.pos.z);
      if (d < bestD) { bestD = d; bestT = i / samples; }
    }
    s.t = bestT;
  }
  STOPS[0].t = 0.0;
  STOPS[STOPS.length - 1].t = 1.0;
}

